package com.bqsqwad.heartbreakhealer.feature.entertainment

/** Five additional original ten-part serials with resolved endings. */
internal object StoryLibraryBatch9 {
    val stories = listOf(
        StorySeries("the_silver_bell", "The Silver Bell", "A village school investigates the history of a bell that once called the community together.", listOf(
            StoryPart(1, "A Bell in a Box", listOf("A silver bell appeared in the school office with a note asking the students to find its original home. The headteacher recognised it from an old photograph of the village square.", "The photograph showed the bell hanging outside a reading room that had closed many years earlier.")),
            StoryPart(2, "The Reading Room", listOf("The local archive held a record of the reading room and its volunteer keepers. It had offered evening lessons and a place for families to borrow books.", "The final entry mentioned that the bell had been moved during renovations, but the destination was missing.")),
            StoryPart(3, "The Caretaker's Memory", listOf("A retired caretaker remembered wrapping the bell in cloth and placing it in a storage cupboard at the school. He thought it had been collected later by a community group.", "The group had since become a neighbourhood association. Its secretary agreed to check the old meeting minutes.")),
            StoryPart(4, "The Minute Book", listOf("The minutes recorded that the bell was loaned to the school for a history exhibition, not permanently donated. The association wanted it returned when the reading room reopened.", "The students realised the bell was not simply a forgotten object; it belonged to a community that had kept its story alive.")),
            StoryPart(5, "A Room to Reopen", listOf("The council confirmed that the old reading room was now used for storage but could be assessed for community use. The students asked whether it could host a small reading club again.", "The council required a building inspection, an access plan, and a named group responsible for maintenance.")),
            StoryPart(6, "The Inspection", listOf("The inspection found that the room needed lighting repairs and a safer entrance before it could host visitors. The association agreed to apply for a small community grant.", "The students prepared a display about the reading room's history while the adults arranged the necessary work.")),
            StoryPart(7, "Books for the Shelves", listOf("Residents donated books, but the librarian helped the group check condition, age suitability, and catalogue details. They set up a simple borrowing record.", "A former volunteer brought a photograph of the first reading club and recognised several names in the students' archive.")),
            StoryPart(8, "The Bell's Return", listOf("After the room passed inspection, the association arranged a reopening day. The school returned the bell according to the loan record, and the secretary signed a receipt.", "The bell was placed beside the entrance, with a sign explaining that it would be rung only for scheduled community events.")),
            StoryPart(9, "The First Reading", listOf("Children and older residents attended the first reading session. A former volunteer read from a book that had been part of the original collection, while students displayed the history they had uncovered.", "The association published opening times and a volunteer rota so the room could remain available consistently.")),
            StoryPart(10, "A Sound for Everyone", listOf("The silver bell rang once to mark the reading room's reopening. The school kept a copy of the archive records, and the association preserved the original minute book.", "The bell had not been lost or stolen; it had been safely loaned and then forgotten in a long chain of changes. The students had restored its history, returned it to its community, and helped the reading room begin a new chapter."))
        )),
        StorySeries("the_moonlight_greenhouse", "The Moonlight Greenhouse", "A night-blooming plant leads two friends to discover a local botanist's forgotten research.", listOf(
            StoryPart(1, "The Flower After Dark", listOf("During a school science project, Ife noticed a flower opening only after sunset in the greenhouse. Its label had faded, leaving only a date and the initials 'M.K.'.", "Her teacher explained that the greenhouse once hosted a local botanist who studied plants that bloomed at night.")),
            StoryPart(2, "The Research Notebook", listOf("The school archive contained a notebook with careful drawings and observations. The botanist had recorded flowering times, temperature, and the insects that visited the plants.", "A note in the margin said the final collection had been moved to a university garden for safekeeping.")),
            StoryPart(3, "The University Garden", listOf("The university curator confirmed that a collection from the school had been received, but the catalogue used a different plant name. The curator invited the students to compare the drawings.", "They found a match in the old catalogue and discovered that the botanist was Dr Mariam Kalu, who had helped establish the university's public garden.")),
            StoryPart(4, "A Researcher's Family", listOf("Dr Kalu's daughter shared letters describing her mother's work with schoolchildren. She said the greenhouse had been important because it allowed students to observe plants over several seasons.", "The letters also mentioned a set of glass labels that had been made by the students. The family wondered whether any had survived.")),
            StoryPart(5, "The Glass Labels", listOf("A retired laboratory assistant found the labels in a protective case. Each one recorded a plant's common name, scientific name, and the student who had cared for it.", "The assistant explained that the labels had been stored after a shelf cracked. The greenhouse had closed for repairs before the collection could be returned.")),
            StoryPart(6, "Restoring the Records", listOf("The teacher and curator checked the plant identifications and corrected two outdated names. The students created a digital catalogue while preserving photographs of the original labels.", "They agreed not to publish the botanist's private correspondence, using only research notes that the family had approved for educational display.")),
            StoryPart(7, "A Night Observation", listOf("The greenhouse was inspected and approved for supervised evening access during a special science event. Students observed the flower opening and recorded the time without disturbing the plant.", "The curator explained how pollinators and environmental conditions influenced the process. The students learned to distinguish observation from assumption.")),
            StoryPart(8, "The Public Garden", listOf("The university garden hosted a display about Dr Kalu's research and invited the school to contribute its restored notebook and labels. The family attended and shared approved photographs.", "The display credited the students who had cared for the plants and the assistants who maintained the collection.")),
            StoryPart(9, "A New Partnership", listOf("The school and university created an annual plant-observation project with clear supervision, record-keeping, and permissions. Students could compare observations over time and learn from professional botanists.", "Ife's class chose to study a different plant the following term, ensuring the project would continue beyond one discovery.")),
            StoryPart(10, "Under the Moonlight", listOf("At the final evening session, the flower opened beneath the greenhouse lights. Ife placed a copy of the restored label beside it and thanked Dr Kalu's family for sharing the history.", "The mystery had led to a research partnership, the records were preserved accurately, and the greenhouse had become a place for careful discovery again. Ife understood that science was not only about finding something unusual; it was also about recording it honestly and giving credit to everyone who helped."))
        )),
        StorySeries("the_second_hand_shop", "The Second-Hand Shop", "A student volunteer uncovers the stories behind donated objects and helps a shop create a respectful local archive.", listOf(
            StoryPart(1, "The Suitcase of Objects", listOf("A school volunteer shift at a second-hand shop began with a suitcase full of labelled objects: a chess medal, a recipe card, a theatre ticket, and a small wooden bird.", "The shop manager explained that the donor wanted the items to find new homes, but had also left notes about their histories.")),
            StoryPart(2, "A Medal's Story", listOf("The chess medal belonged to a former student who had represented the town in a youth tournament. The shop found the winner's name in an old newspaper and contacted the family.", "The family said the medal could be displayed temporarily, provided the donor's wishes were respected and it was not sold.")),
            StoryPart(3, "The Recipe Card", listOf("The recipe card carried a family name and a note that it had been shared at a community fundraiser. A local history group recognised the event and had a photograph of the original cooks.", "The group asked the shop to record the recipe's origin and contributors rather than publish it as an anonymous traditional dish.")),
            StoryPart(4, "The Theatre Ticket", listOf("The ticket came from the first performance at a small theatre that had since become a youth centre. The centre's director found a programme listing local writers and performers.", "Several performers were still active in the arts community and agreed to share memories for a display.")),
            StoryPart(5, "The Wooden Bird", listOf("A craft teacher recognised the wooden bird as a piece made in a workshop for young people learning carving and design. The original maker's name was written beneath the base.", "The shop contacted the maker, who was pleased to see the bird again and offered to demonstrate the design process at the youth centre.")),
            StoryPart(6, "A Consent Catalogue", listOf("The student proposed a catalogue that recorded each object's history only with permission from donors and families. Personal addresses and private details would not be included.", "The shop manager approved the idea and created clear choices: display, return to family, or offer for sale according to the donor's instructions.")),
            StoryPart(7, "The Community Display", listOf("The local history group hosted a display featuring the medal, recipe card, theatre programme, and wooden bird. Each item had a short verified story and a note about its owner or creator.", "Visitors recognised some names and added memories, but the organisers checked every new claim before including it.")),
            StoryPart(8, "A Missing Owner", listOf("One object remained unidentified: a small ticket from a bus route that no longer existed. A transport historian recognised the route and found a date that matched a town festival.", "The festival archive listed a volunteer group that had organised transport for elderly residents. The ticket had likely been kept as a thank-you token.")),
            StoryPart(9, "The Volunteer Reunion", listOf("The former volunteers met at the youth centre and confirmed the ticket's story. They donated a copy of their group photograph and asked that the original ticket remain with the shop.", "The shop added a simple process for future donations so that objects would not lose their histories when they changed hands.")),
            StoryPart(10, "More Than Things", listOf("The suitcase was empty now, but its objects had found appropriate places: some with families, some in a display, and one back with its maker. The shop kept the verified catalogue for future volunteers.", "The student learned that second-hand objects could carry valuable memories, but those memories deserved accuracy and consent. The project had preserved the stories without treating private lives as public property, and the shop had become a more thoughtful part of the community."))
        )),
        StorySeries("the_hilltop_radio", "The Hilltop Radio", "A school radio team restores a local broadcast archive and gives young voices a responsible platform.", listOf(
            StoryPart(1, "A Voice in the Static", listOf("The school media club found an old radio receiver in a cupboard. When it was switched on by the technician, it picked up a faint recording of a school announcement from years earlier.", "A label said 'Hilltop Radio Archive'. The media teacher explained that students once produced a weekly programme for the neighbourhood.")),
            StoryPart(2, "The Broadcast Log", listOf("The library held a log listing programme titles, presenters, and topics. One entry was marked 'final broadcast', but there was no recording attached.", "The log named a former teacher who had supervised the station. The students wrote to her through the school office.")),
            StoryPart(3, "The Teacher's Box", listOf("The retired teacher still had a box of tapes and scripts. She said the station closed when the school changed its media equipment, but the students had continued producing announcements for assemblies.", "She agreed to let the school digitise selected recordings after the contributors or their families had approved them.")),
            StoryPart(4, "The Missing Episode", listOf("One script described an episode about local flood preparedness, featuring a community organiser and a weather observer. The recording was missing, but the script included a date and a list of guests.", "The students located the organiser, who remembered the programme and had kept a copy of the broadcast on a personal archive drive.")),
            StoryPart(5, "A Clear Permission", listOf("The organiser agreed to share the recording for educational use. The school checked that everyone featured had consented or that the recording could be safely edited to remove unapproved personal details.", "The students learned that preserving audio also required care for the people whose voices were recorded.")),
            StoryPart(6, "A New Studio Plan", listOf("The media teacher proposed a small school radio programme with clear editorial review, a schedule, and rules against sharing rumours or private information.", "The principal approved a trial. Students would prepare scripts, verify facts, and have a teacher review each episode before broadcast.")),
            StoryPart(7, "The First Programme", listOf("The first new episode covered school events and a short interview with the librarian. The team introduced each speaker and explained how listeners could send feedback through the official school channel.", "The broadcast went smoothly, and the students saved the script and recording with the date and contributor permissions.")),
            StoryPart(8, "The Archive Display", listOf("The school hosted a listening afternoon where visitors could hear approved excerpts from the old broadcasts. The retired teacher explained how the station had helped students practise clear communication.", "The media club displayed the old log beside the new programme schedule, showing how the project had evolved.")),
            StoryPart(9, "A Voice for the Future", listOf("The students planned a series featuring local history, science, arts, and public service information. Each episode would include sources and a correction process if a mistake was discovered.", "The community organiser offered to review the flood-preparedness episode for accuracy before it was shared.")),
            StoryPart(10, "Broadcasting Responsibly", listOf("Hilltop Radio returned as a supervised school programme, with an archive, consent records, and a clear editorial process. The old recordings were preserved, and the missing episode was restored to the collection.", "The students understood that a microphone could make a voice travel far, so it carried a responsibility to be fair and accurate. The static had given way to a clear signal, and the school had found a way to keep its stories moving."))
        )),
        StorySeries("the_pocket_garden", "The Pocket Garden", "A small unused corner becomes a welcoming green space after neighbours learn to work together.", listOf(
            StoryPart(1, "The Narrow Corner", listOf("A narrow strip beside the apartment block collected dust and fallen leaves. Zainab imagined a pocket garden there, but the residents' committee said the space had no agreed use.", "She asked the building manager for the property plan before making suggestions. The plan showed the strip was shared space and had to remain clear for access.")),
            StoryPart(2, "The Residents' Meeting", listOf("At the next meeting, Zainab presented a small garden idea with containers that would not block the walkway. Some residents liked it; others worried about maintenance and insects.", "The committee asked her to gather advice from a horticulture volunteer and prepare a practical plan.")),
            StoryPart(3, "The Plant List", listOf("The volunteer recommended suitable container plants and explained how to avoid standing water and keep the area tidy. The team chose a few low-maintenance varieties and included a cleaning rota.", "Zainab checked which residents had allergies or access concerns without asking anyone to disclose private medical details. The design left a wide clear route.")),
            StoryPart(4, "The Budget", listOf("The first budget included too many decorative items. Zainab reduced it to containers, soil, plants, labels, and basic maintenance supplies.", "A nearby nursery offered a discount, while the residents agreed on a small shared contribution with a clear record of spending.")),
            StoryPart(5, "Permission to Begin", listOf("The property manager approved the design after confirming that it did not affect drainage, access, or building services. The committee recorded the approval and named two coordinators.", "The residents waited until the installation date and agreed that no one would attach anything to the building without permission.")),
            StoryPart(6, "Planting Day", listOf("Neighbours assembled the containers and planted the selected varieties. Children helped add labels while adults checked that the walkway remained clear.", "The horticulture volunteer explained watering and pruning, and the coordinators placed a maintenance calendar near the entrance.")),
            StoryPart(7, "The First Challenge", listOf("A week later, strong wind tipped one container. The residents moved it to a more sheltered approved spot and checked that the other containers were stable.", "They added the adjustment to the maintenance notes so future volunteers would know what had changed.")),
            StoryPart(8, "A Garden for Quiet Moments", listOf("A resident suggested a small bench, but the access review showed there was not enough room. Instead, the committee added a nearby seating suggestion to the building's shared courtyard plan.", "The pocket garden remained simple, but residents began stopping to look at the plants and exchange gardening tips.")),
            StoryPart(9, "The Monthly Check", listOf("The coordinators reviewed plant health, cleaning, and costs each month. When one plant did not thrive, they replaced it with a better-suited variety after checking with the volunteer.", "The committee kept the project open to feedback and made sure responsibilities did not fall on one household.")),
            StoryPart(10, "A Small Space, Shared Well", listOf("At the end of the season, the residents reviewed the garden and renewed the maintenance rota. The once-neglected strip was tidy, green, and still fully accessible.", "Zainab added a small sign thanking the neighbours who helped. The pocket garden was not large, but it had proved that shared spaces could improve through permission, thoughtful design, and shared care. The project ended with a living space the residents could maintain together."))
        ))
    )
}
